CELLS = ['%matplotlib inline\nfrom d2l import torch as d2l\nimport math\nimport torch\n', 'def f(x1, x2):  # 目标函数\n    return x1 ** 2 + 2 * x2 ** 2\n\ndef f_grad(x1, x2):  # 目标函数的梯度\n    return 2 * x1, 4 * x2\n', 'def sgd(x1, x2, s1, s2, f_grad):\n    g1, g2 = f_grad(x1, x2)\n    # 模拟有噪声的梯度\n    g1 += d2l.normal(0.0, 1, (1,)).item()\n    g2 += d2l.normal(0.0, 1, (1,)).item()\n    eta_t = eta * lr()\n    return (x1 - eta_t * g1, x2 - eta_t * g2, 0, 0)\n', 'def constant_lr():\n    return 1\n\neta = 0.1\nlr = constant_lr  # 常数学习速度\nd2l.show_trace_2d(f, d2l.train_2d(sgd, steps=50, f_grad=f_grad))\n', 'def exponential_lr():\n    # 在函数外部定义，而在内部更新的全局变量\n    global t\n    t += 1\n    return math.exp(-0.1 * t)\n\nt = 1\nlr = exponential_lr\nd2l.show_trace_2d(f, d2l.train_2d(sgd, steps=1000, f_grad=f_grad))\n', 'def polynomial_lr():\n    # 在函数外部定义，而在内部更新的全局变量\n    global t\n    t += 1\n    return (1 + 0.1 * t) ** (-0.5)\n\nt = 1\nlr = polynomial_lr\nd2l.show_trace_2d(f, d2l.train_2d(sgd, steps=50, f_grad=f_grad))\n', '%matplotlib inline\nfrom d2l import torch as d2l\nimport torch\nfrom torch import nn\nimport numpy as np\n\ntimer = d2l.Timer()\nA = torch.zeros(256, 256)\nB = torch.randn(256, 256)\nC = torch.randn(256, 256)\n', '# 逐元素计算A=BC（缩小到 16 × 16，只检查结果）\nA = torch.zeros(16, 16); B2 = torch.randn(16, 16); C2 = torch.randn(16, 16)\nfor i in range(16):\n    for j in range(16):\n        A[i, j] = torch.dot(B2[i, :], C2[:, j])\nbool(torch.allclose(A, torch.mm(B2, C2), atol=1e-5))', 'for j in range(16):\n    A[:, j] = torch.mv(B2, C2[:, j])\nbool(torch.allclose(A, torch.mm(B2, C2), atol=1e-5)), len(timer.times) >= 0', 'A = torch.mm(B, C)\ntimer.stop()\ntype(timer.avg()).__name__, len(timer.cumsum()) == len(timer.times)', 'for j in range(0, 256, 64):\n    A[:, j:j+64] = torch.mm(B, C[:, j:j+64])\nbool(torch.allclose(A, torch.mm(B, C), atol=1e-4))', "#@save\nd2l.DATA_HUB['airfoil'] = (d2l.DATA_URL + 'airfoil_self_noise.dat',\n                           '76e5be1548fd8222e5074cf0faae75edff8cf93f')\n\n#@save\ndef get_data_ch11(batch_size=10, n=1500):\n    data = np.genfromtxt(d2l.download('airfoil'),\n                         dtype=np.float32, delimiter='\\t')\n    data = torch.from_numpy((data - data.mean(axis=0)) / data.std(axis=0))\n    data_iter = d2l.load_array((data[:n, :-1], data[:n, -1]),\n                               batch_size, is_train=True)\n    return data_iter, data.shape[1]-1\n", "data = np.genfromtxt(d2l.download('airfoil'), dtype=np.float32, delimiter='\\t')\ndata.shape, data.dtype, data[:2], data.mean(axis=0), data.std(axis=0)", 't = torch.from_numpy((data - data.mean(axis=0)) / data.std(axis=0))\nt.shape, t.dtype, t[:2], torch.square(torch.tensor([-2.0, 3.0])), torch.sign(torch.tensor([-2.0, 0.0, 3.0]))', "def sgd(params, states, hyperparams):\n    for p in params:\n        p.data.sub_(hyperparams['lr'] * p.grad)\n        p.grad.data.zero_()\n", "#@save\ndef train_ch11(trainer_fn, states, hyperparams, data_iter,\n               feature_dim, num_epochs=2):\n    # 初始化模型\n    w = torch.normal(mean=0.0, std=0.01, size=(feature_dim, 1),\n                     requires_grad=True)\n    b = torch.zeros((1), requires_grad=True)\n    net, loss = lambda X: d2l.linreg(X, w, b), d2l.squared_loss\n    # 训练模型\n    animator = d2l.Animator(xlabel='epoch', ylabel='loss',\n                            xlim=[0, num_epochs], ylim=[0.22, 0.35])\n    n, timer = 0, d2l.Timer()\n    for _ in range(num_epochs):\n        for X, y in data_iter:\n            l = loss(net(X), y).mean()\n            l.backward()\n            trainer_fn([w, b], states, hyperparams)\n            n += X.shape[0]\n            if n % 200 == 0:\n                timer.stop()\n                animator.add(n/X.shape[0]/len(data_iter),\n                             (d2l.evaluate_loss(net, data_iter, loss),))\n                timer.start()\n    print(f'loss: {animator.Y[0][-1]:.3f}, {timer.avg():.3f} sec/epoch')\n    return timer.cumsum(), animator.Y[0]\n", "def train_sgd(lr, batch_size, num_epochs=2):\n    data_iter, feature_dim = get_data_ch11(batch_size)\n    return train_ch11(\n        sgd, None, {'lr': lr}, data_iter, feature_dim, num_epochs)\n\ngd_res = train_sgd(1, 1500, 10)\n", 'sgd_res = train_sgd(0.005, 1)\n', 'mini1_res = train_sgd(.4, 100)\n', 'mini2_res = train_sgd(.05, 10)\n', "d2l.set_figsize([6, 3])\nd2l.plot(*list(map(list, zip(gd_res, sgd_res, mini1_res, mini2_res))),\n         'time (sec)', 'loss', xlim=[1e-2, 10],\n         legend=['gd', 'sgd', 'batch size=100', 'batch size=10'])\nd2l.plt.gca().set_xscale('log')\n", "#@save\ndef train_concise_ch11(trainer_fn, hyperparams, data_iter, num_epochs=4):\n    # 初始化模型\n    net = nn.Sequential(nn.Linear(5, 1))\n    def init_weights(m):\n        if type(m) == nn.Linear:\n            torch.nn.init.normal_(m.weight, std=0.01)\n    net.apply(init_weights)\n\n    optimizer = trainer_fn(net.parameters(), **hyperparams)\n    loss = nn.MSELoss(reduction='none')\n    animator = d2l.Animator(xlabel='epoch', ylabel='loss',\n                            xlim=[0, num_epochs], ylim=[0.22, 0.35])\n    n, timer = 0, d2l.Timer()\n    for _ in range(num_epochs):\n        for X, y in data_iter:\n            optimizer.zero_grad()\n            out = net(X)\n            y = y.reshape(out.shape)\n            l = loss(out, y)\n            l.mean().backward()\n            optimizer.step()\n            n += X.shape[0]\n            if n % 200 == 0:\n                timer.stop()\n                # MSELoss计算平方误差时不带系数1/2\n                animator.add(n/X.shape[0]/len(data_iter),\n                             (d2l.evaluate_loss(net, data_iter, loss) / 2,))\n                timer.start()\n    print(f'loss: {animator.Y[0][-1]:.3f}, {timer.avg():.3f} sec/epoch')\n", "data_iter, _ = get_data_ch11(10)\ntrainer = torch.optim.SGD\ntrain_concise_ch11(trainer, {'lr': 0.01}, data_iter)\n", '%matplotlib inline\nfrom d2l import torch as d2l\nimport torch\n\neta = 0.4\ndef f_2d(x1, x2):\n    return 0.1 * x1 ** 2 + 2 * x2 ** 2\ndef gd_2d(x1, x2, s1, s2):\n    return (x1 - eta * 0.2 * x1, x2 - eta * 4 * x2, 0, 0)\n\nd2l.show_trace_2d(f_2d, d2l.train_2d(gd_2d))\n', 'eta = 0.6\nd2l.show_trace_2d(f_2d, d2l.train_2d(gd_2d))\n', 'def momentum_2d(x1, x2, v1, v2):\n    v1 = beta * v1 + 0.2 * x1\n    v2 = beta * v2 + 4 * x2\n    return x1 - eta * v1, x2 - eta * v2, v1, v2\n\neta, beta = 0.6, 0.5\nd2l.show_trace_2d(f_2d, d2l.train_2d(momentum_2d))\n', 'eta, beta = 0.6, 0.25\nd2l.show_trace_2d(f_2d, d2l.train_2d(momentum_2d))\n', "d2l.set_figsize()\nbetas = [0.95, 0.9, 0.6, 0]\nfor beta in betas:\n    x = d2l.numpy(d2l.arange(40))\n    d2l.plt.plot(x, beta ** x, label=f'beta = {beta:.2f}')\nd2l.plt.xlabel('time')\nd2l.plt.legend();\n", 'def init_momentum_states(feature_dim):\n    v_w = d2l.zeros((feature_dim, 1))\n    v_b = d2l.zeros(1)\n    return (v_w, v_b)\n', "def sgd_momentum(params, states, hyperparams):\n    for p, v in zip(params, states):\n        with torch.no_grad():\n            v[:] = hyperparams['momentum'] * v + p.grad\n            p[:] -= hyperparams['lr'] * v\n        p.grad.data.zero_()\n", "def train_momentum(lr, momentum, num_epochs=2):\n    d2l.train_ch11(sgd_momentum, init_momentum_states(feature_dim),\n                   {'lr': lr, 'momentum': momentum}, data_iter,\n                   feature_dim, num_epochs)\n\ndata_iter, feature_dim = d2l.get_data_ch11(batch_size=10)\ntrain_momentum(0.02, 0.5)\n", 'train_momentum(0.01, 0.9)\n', 'train_momentum(0.005, 0.9)\n', "trainer = torch.optim.SGD\nd2l.train_concise_ch11(trainer, {'lr': 0.005, 'momentum': 0.9}, data_iter)\n", "lambdas = [0.1, 1, 10, 19]\neta = 0.1\nd2l.set_figsize((6, 4))\nfor lam in lambdas:\n    t = d2l.numpy(d2l.arange(20))\n    d2l.plt.plot(t, (1 - eta * lam) ** t, label=f'lambda = {lam:.2f}')\nd2l.plt.xlabel('time')\nd2l.plt.legend();\n", "%matplotlib inline\nfrom d2l import torch as d2l\nimport torch\n\ndef init_adam_states(feature_dim):\n    v_w, v_b = d2l.zeros((feature_dim, 1)), d2l.zeros(1)\n    s_w, s_b = d2l.zeros((feature_dim, 1)), d2l.zeros(1)\n    return ((v_w, s_w), (v_b, s_b))\n\ndef adam(params, states, hyperparams):\n    beta1, beta2, eps = 0.9, 0.999, 1e-6\n    for p, (v, s) in zip(params, states):\n        with torch.no_grad():\n            v[:] = beta1 * v + (1 - beta1) * p.grad\n            s[:] = beta2 * s + (1 - beta2) * torch.square(p.grad)\n            v_bias_corr = v / (1 - beta1 ** hyperparams['t'])\n            s_bias_corr = s / (1 - beta2 ** hyperparams['t'])\n            p[:] -= hyperparams['lr'] * v_bias_corr / (torch.sqrt(s_bias_corr)\n                                                       + eps)\n        p.grad.data.zero_()\n    hyperparams['t'] += 1\n", "data_iter, feature_dim = d2l.get_data_ch11(batch_size=10)\nd2l.train_ch11(adam, init_adam_states(feature_dim),\n               {'lr': 0.01, 't': 1}, data_iter, feature_dim);\n", "trainer = torch.optim.Adam\nd2l.train_concise_ch11(trainer, {'lr': 0.01}, data_iter)\n", "def yogi(params, states, hyperparams):\n    beta1, beta2, eps = 0.9, 0.999, 1e-3\n    for p, (v, s) in zip(params, states):\n        with torch.no_grad():\n            v[:] = beta1 * v + (1 - beta1) * p.grad\n            s[:] = s + (1 - beta2) * torch.sign(\n                torch.square(p.grad) - s) * torch.square(p.grad)\n            v_bias_corr = v / (1 - beta1 ** hyperparams['t'])\n            s_bias_corr = s / (1 - beta2 ** hyperparams['t'])\n            p[:] -= hyperparams['lr'] * v_bias_corr / (torch.sqrt(s_bias_corr)\n                                                       + eps)\n        p.grad.data.zero_()\n    hyperparams['t'] += 1\n\ndata_iter, feature_dim = d2l.get_data_ch11(batch_size=10)\nd2l.train_ch11(yogi, init_adam_states(feature_dim),\n               {'lr': 0.01, 't': 1}, data_iter, feature_dim);\n"]
